from pwn import *

def try_path(choice, password):
    try:
        r = remote('rev.chal.csaw.io', 5000)
        print("\nStarting new connection...")

        # Initial prompt
        r.recvuntil(b"Choice: ")
        print(f"Sending choice: {choice}")
        r.sendline(str(choice).encode())

        # Get response and check for password prompt
        response = r.recvuntil(b"Password:", timeout=2)
        print("Response received:")
        print(response.decode('latin-1'))

        # Send password
        print(f"Sending password: {password}")
        r.sendline(str(password).encode())

        # Get final response
        try:
            while True:
                response = r.recv(timeout=1)
                if not response:
                    break
                print(response.decode('latin-1'))
        except EOFError:
            pass

    except Exception as e:
        print(f"Error occurred: {e}")
    finally:
        r.close()

def main():
    # Test each path with its corresponding password
    paths = {
        1: "4013828393",
        2: "1118844294",
        3: "3000956154"
    }

    for choice, password in paths.items():
        try_path(choice, password)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from pwn import *
import time

def try_path(choice, password):
    try:
        # Set a shorter timeout
        r = remote('rev.chal.csaw.io', 5000, timeout=5)
        print(f"\nTrying path: Choice {choice} with password {password}")

        # Initial game menu
        r.recvuntil(b"Choice: ")
        r.sendline(str(choice).encode())

        # Handle potential password prompt
        try:
            response = r.recvuntil(b"Password:", timeout=2)
            print("Got password prompt:")
            print(response.decode('latin-1'))

            # Send password
            r.sendline(password.encode())

            # Get response after password
            try:
                result = r.recvall(timeout=3)
                if result:
                    print("Response after password:")
                    print(result.decode('latin-1'))
            except:
                pass

        except EOFError:
            print("No password prompt received")

    except Exception as e:
        print(f"Error: {e}")
    finally:
        try:
            r.close()
        except:
            pass

def main():
    # Define paths and passwords
    paths = {
        1: "4013828393",  # Room 0
        2: "1118844294",  # Room 1
        3: "3000956154",  # Room 2
    }

    # Try each path
    for choice, password in paths.items():
        try_path(choice, password)
        time.sleep(1)  # Small delay between attempts

if __name__ == "__main__":
    main()

